def transform(grid):
    h = len(grid)
    w = len(grid[0])

    # Find 8 column position (based on width parity)
    if w % 2 == 1:
        eight_col = w // 2
    else:
        eight_col = w // 2 + 1

    # Find wall column (vertical line of 2s)
    wall_col = -1
    for c in range(w):
        if grid[0][c] == 2:
            wall_col = c
            break

    # Background and object color detection
    bg = grid[0][0]
    object_color = None
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != bg and val != 2 and val != 8:
                object_color = val
                break
        if object_color:
            break

    # Create result grid as copy
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Set 8s first
    for r in range(h):
        result[r][eight_col] = 8

    # Fill space between 8 column and wall with object shape
    # Collect all object pixels and their bounding box
    if object_color:
        positions = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] == object_color:
                    positions.append((r, c))

        # Calculate bounding box of the object
        if positions:
            min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
            min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)

            # Fill the area between 8 column and wall with copies of the object
            # The object is placed with the same orientation
            if eight_col < wall_col:
                # Wall is to the right, fill from eight_col+1 to wall-1
                for r in range(min_r, max_r + 1):
                    for c in range(eight_col + 1, wall_col):
                        # Copy object to this position
                        orig_c = c - (eight_col + 1) + min_c
                        if min_c <= orig_c <= max_c:
                            orig_r = r - min_r
                            if min_c <= orig_c <= max_c:
                                result[r][c] = object_color
            else:
                # Wall is to the left, fill from wall+1 to eight_col-1
                for r in range(min_r, max_r + 1):
                    for c in range(wall_col + 1, eight_col):
                        orig_c = c - (wall_col + 1) + min_c
                        if min_c <= orig_c <= max_c:
                            result[r][c] = object_color

    return result
